func rsFits(on *port.Cells, cpn int32, obj int32) bool {
	// Can the caption cpn (its kind in `aux`: 1 figure-like, 2 table-like) belong to the object: a table or a figure
	// of the right kind, without a caption already?
	if (obj < 0) || (cpn < 0) {
		return 0 == 1
	}
	if model.NodeKind(on, cpn) != model.NkCaption() {
		return 0 == 1
	}
	var ck int32 = model.NodeAux(on, cpn)
	var ok int32 = model.NodeKind(on, obj)
	if rsHasCaption(on, obj) {
		return 0 == 1
	}
	if (ck == 2) && (ok == model.NkTable()) {
		return 1 == 1
	}
	if (ck == 1) && (ok == model.NkFigure()) {
		return 1 == 1
	}
	return 0 == 1
}

func rsGrab(on *port.Cells, obj int32) bool {
	// Does the object (a table or a figure) take the caption that follows it? Not when the caption is a table's and
	// a table follows it with none: a table's caption is above it.
	var q int32 = model.NodeNext(on, obj)
	if !rsFits(on, q, obj) {
		return 0 == 1
	}
	if model.NodeKind(on, obj) == model.NkTable() {
		var r int32 = model.NodeNext(on, q)
		if (r >= 0) && (model.NodeKind(on, r) == model.NkTable()) && !rsHasCaption(on, r) {
			return 0 == 1
		}
	}
	return 1 == 1
}

